      clock_group: "secure",
      reset_connections: {rst_ni: "lc_io_div4", rst_edn_ni: "lc"},
      base_addr: {
        hart: "0x30160000",
      },
      param_decl: {
        EscNumSeverities: "4",
        EscPingCountWidth: "16"
      },
      attr: "ipgen",
    },
    { name: "spi_host0",
      type: "spi_host",
      clock_srcs: {clk_i: "io_div4"},
      clock_group: "peri",
      reset_connections: {rst_ni: "spi_host0"},
      base_addr: {
        hart: "0x30300000",
      },
    },
    { name: "pwrmgr_aon",
      type: "pwrmgr",
      template_type: "pwrmgr",
      // TODO: RS, fix after pwrmgr fix is merged
      // param_decl: {
      //   PwrFsmWaitForExtRst: "1"
      // }
      clock_group: "powerup",
      clock_srcs: {
        clk_i: "io_div4",
