  // The reset stretching assertion.
  `ASSERT(StablePorToAonRise_A,
          PorStable_S |-> ##[0:(PorCycles.rise.max-PorCycles.rise.min)]
          !aon_por_n_i || resets_o.rst_por_aon_n[0],
          clk_aon_i, disable_sva)

  // The scan reset to Por.
