  typedef push_pull_agent_cfg#(
    .DeviceDataWidth(ibex_pkg::SCRAMBLE_NONCE_W + ibex_pkg::SCRAMBLE_KEY_W)
    ) scrambling_key_agent_cfg;

  `include "core_ibex_vseqr.sv"
  `include "core_ibex_env_cfg.sv"
