	cout << "--------------------------------------------------------------\n";
	cout << "   Simulation Completed\n";
	cout << "--------------------------------------------------------------\n";

	logFile.close();
	sigFile.close();
    programFile.close();
    pcFile.close();

	delete cva5Tracer;

	exit(EXIT_SUCCESS);
}

