module hpdcache_prio_bin_encoder
    //  Parameters
#(
    parameter  int unsigned N = 0,
    localparam int unsigned N_LOG2 = $clog2(N)
)
    //  Ports
(
    input  logic [N-1:0]      val_i,
    output logic [N_LOG2-1:0] val_o
);

    always_comb begin
        val_o = '0;
        for (int i = N-1; i >= 0; i--)
            if (val_i[i]) val_o = N_LOG2'(i);
    end
endmodule

